// ===== TEST ONLY - pick a case, then click "Test workflow" =====
// A = P084 from S34, 1500 pcs  -> ~AED 35,835  -> no approval needed -> sent
// B = P017 from S20, 1000 pcs  -> ~AED 126,310 -> approval -> approved -> sent
// C = P017 from S20, 9000 pcs  -> too many for the production plan -> approval rejected -> NOT sent
// D = quote is for S34, but the handoff claims S16 -> mismatch -> blocked, NOT sent
const CASE = 'B';

const cases = {
  A: { part_id: 'P084', supplier_id: 'S34', qty: 1500, mode: 'sea' },
  B: { part_id: 'P017', supplier_id: 'S20', qty: 1000, mode: 'sea' },
  C: { part_id: 'P017', supplier_id: 'S20', qty: 9000, mode: 'sea' },
  D: { part_id: 'P084', supplier_id: 'S34', qty: 1500, mode: 'sea' },
};
return [{ json: { test_case: CASE, ...cases[CASE], p4_url: 'http://host.docker.internal:8000' } }];

const config = {
  approval_limit_aed: 50000
};

const items = $input.all().map(i => i.json);
const results = [];

function validDate(value) {
  const date = String(value ?? '').slice(0, 10);

  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return false;

  const ms = Date.parse(date + 'T00:00:00Z');

  return Number.isFinite(ms) &&
    new Date(ms).toISOString().slice(0, 10) === date;
}

for (const raw of items) {
  const h = raw.handoff ?? raw;

  const errors = [];

  if (h.error) {
    errors.push(
      'Upstream agent failed: ' +
      (typeof h.error === 'string' ? h.error : JSON.stringify(h.error)).slice(0, 300)
    );
  }

  if (h.status === 'shortage_handoff_to_agent4') {
    errors.push('Received the Agent 3 handoff unchanged: Agent 4 did not return a plan.');
  }

  // HARD SAFETY GATES
  if (h.status !== 'ready_for_procurement') {
    errors.push(
      `Handoff status is not ready_for_procurement (got: ${h.status ?? 'missing'}). ` +
      `Agent 4 said: ${String(h.justification ?? h.reasoning_summary ?? 'no reason given').slice(0, 300)}`
    );
  }

  // Only worth reporting when the status does not already explain it.
  if (h.auto_procurement_allowed !== true &&
      h.status === 'ready_for_procurement') {
    errors.push(
      'Handoff claims ready_for_procurement but does not authorize automatic procurement'
    );
  }

  if (h.requires_human_review === true) {
    errors.push('Human review is required before procurement');
  }

  if (h.production_at_risk !== true) {
    errors.push('No confirmed production risk in handoff');
  }

  // Second safety net: never buy something that lands no earlier than the
  // delayed shipment it is meant to replace.
  if (h.late_order === true &&
      h.beats_waiting === false &&
      h.disrupted_shipment_eta) {
    errors.push(
      `Order would arrive ${h.earliest_arrival ?? 'late'}, not earlier than the ` +
      `delayed shipment landing ${h.disrupted_shipment_eta}. Buying adds cost without saving time.`
    );
  }

  // Do not proceed if an upstream safety gate failed.
  if (errors.length) {
    results.push({
      json: {
        ok: false,
        stage: 'blocked_before_procurement',
        status: h.status ?? 'missing',
        handoff_status: h.status ?? 'missing',
        quote_errors: h.quote_errors ?? [],

        advisor_recommendation: h.advisor_recommendation ?? null,
        advisor_recommended_option: h.advisor_recommended_option ?? null,
        advisor_tradeoffs: h.advisor_tradeoffs ?? null,
        advisor_question_for_buyer: h.advisor_question_for_buyer ?? null,

        errors,

        // Enough context for reporting. ok:false still routes this to the
        // stopped branch, so a populated ctx cannot send anything.
        ctx: {
          input: {
            scenario_id: h.scenario_id ?? null,
            incident_id: h.incident_id ?? null,
            quote_id: h.quote_id ?? h.selected_quote_id ?? null,
            supplier_id: h.supplier_id ?? h.selected_supplier_id ?? h.disrupted_supplier_id ?? null,
            // FIX: report both suppliers separately.
            selected_supplier_id: h.selected_supplier_id ?? null,
            disrupted_supplier_id: h.disrupted_supplier_id ?? h.supplier_id ?? null,
            part_id: h.part_id ?? null,
            qty: h.qty ?? h.shortage_quantity ?? null
          }
        }
      }
    });
    continue;
  }

  // FIX: Agent 4 now sends the ORIGINAL disrupted supplier in supplier_id.
  // The supplier to order from is selected_supplier_id.
  // No fallback to h.supplier_id: that would order from the disrupted supplier.
  const disruptedSupplier = String(h.disrupted_supplier_id ?? '')
    .trim().toUpperCase();

  const input = {
    scenario_id: String(h.scenario_id ?? ''),
    incident_id: String(h.incident_id ?? ''),
    quote_id: String(h.quote_id ?? h.selected_quote_id ?? '').trim(),
    // Inside Agent 5, supplier_id means "the supplier we order from".
    supplier_id: String(h.selected_supplier_id ?? '').trim().toUpperCase(),
    disrupted_supplier_id: disruptedSupplier || null,
    part_id: String(h.part_id ?? '').trim().toUpperCase(),
    qty: Number(h.qty ?? h.quantity),
    mode: String(h.mode ?? '').trim().toLowerCase(),

    shortage_qty: Number(h.shortage_qty ?? h.shortage_quantity),
    need_date: h.need_date ?? h.required_by ?? null,

    quote_total_aed: Number(
      h.quote_total_aed ?? h.estimated_total_aed
    ),

    affected_orders: Array.isArray(h.affected_orders)
      ? h.affected_orders.map(String)
      : [],

    source_ids: Array.isArray(h.source_ids)
      ? h.source_ids.map(String)
      : [],

    justification: String(h.justification ?? '').slice(0, 1500),

    reasoning_summary: String(
      h.reasoning_summary ?? ''
    ).slice(0, 1500),

    // Code-built reason from Agent 4 (facts only): why this supplier
    // instead of the disrupted one. Copied into the PO justification.
    selection_reason: String(h.selection_reason ?? '')
      .replace(/\s+/g, ' ').trim().slice(0, 700),
    earliest_arrival: h.earliest_arrival ?? null,
    late_order: h.late_order === true,

    auto_procurement_allowed: true,
    requires_human_review: false
  };

  if (!/^Q-\d{3,}$/.test(input.quote_id)) {
    errors.push('Missing or invalid quote_id');
  }

  if (!/^S\d{2}$/.test(input.supplier_id)) {
    errors.push('Missing or invalid selected_supplier_id');
  }

  // FIX: never order from the supplier that caused the disruption.
  if (disruptedSupplier && input.supplier_id === disruptedSupplier) {
    errors.push('Selected supplier is the disrupted supplier');
  }

  if (!/^P\d{3}$/.test(input.part_id)) {
    errors.push('Missing or invalid part_id');
  }

  if (!Number.isSafeInteger(input.qty) || input.qty <= 0) {
    errors.push('qty must be a positive whole number');
  }

  if (!['sea', 'air'].includes(input.mode)) {
    errors.push('mode must be sea or air');
  }

  if (!Number.isFinite(input.quote_total_aed) ||
      input.quote_total_aed <= 0) {
    errors.push('Invalid quote total');
  }

  if (!Number.isSafeInteger(input.shortage_qty) ||
      input.shortage_qty <= 0) {
    errors.push('Invalid shortage quantity');
  }

  if (!validDate(input.need_date)) {
    errors.push('need_date must be a valid YYYY-MM-DD date');
  }

  results.push({
    json: {
      ok: errors.length === 0,
      stage: 'validate_input',
      errors,
      ctx: errors.length === 0
        ? { config, input }
        : null
    }
  });
}

return results;

// FIX: handle EVERY item, not only the first one.
// Profile responses come back in the same order as the handoffs that passed 'Input OK?'.
const handoffs = $('1. Validate handoff').all()
  .map(i => i.json)
  .filter(j => j && j.ok === true && j.ctx);

const responses = $input.all();

return responses.map((item, index) => {
  const base = handoffs[index];

  if (!base) {
    return {
      json: {
        ok: false,
        stage: 'supplier_check',
        errors: ['Matching validated handoff is missing.'],
        ctx: null
      }
    };
  }

  // Own copy per item, so items never share data.
  const ctx = JSON.parse(JSON.stringify(base.ctx));

  const r = item.json ?? {};
  const p = r.result ?? r;
  const errors = [];

  if (p.detail) errors.push('supplier lookup failed: ' + JSON.stringify(p.detail));

  // Guard: the profile must belong to the supplier in this handoff.
  if (!p.detail && p.supplier_id &&
      String(p.supplier_id).trim().toUpperCase() !== ctx.input.supplier_id) {
    errors.push('Supplier profile does not match the handoff supplier.');
  }

  const preferred = p.preferred_for_parts ?? [];
  const alternates = p.qualified_alternate_for_parts ?? [];
  const qualified = preferred.includes(ctx.input.part_id) || alternates.includes(ctx.input.part_id);
  if (!p.detail && !qualified) errors.push(`${ctx.input.supplier_id} is not qualified for ${ctx.input.part_id}`);

  const domain = String(p.email_domain ?? '').toLowerCase().trim();
  if (!p.detail && !domain) errors.push('supplier has no known email domain');

  ctx.supplier = {
    supplier_id: ctx.input.supplier_id,
    supplier_name: p.supplier_name ?? '',
    email_domain: domain,
    role: preferred.includes(ctx.input.part_id) ? 'preferred' : 'qualified_alternate',
  };
  // Recipient ALWAYS comes from the trusted supplier record, never from an email or another agent
  ctx.recipient = domain ? `orders@${domain}` : '';

  return { json: { ok: errors.length === 0, stage: 'supplier_check', errors, ctx } };
});

