const handoffs = $('3b. Read OpenAI answer').all();
const responses = $input.all();

function parseObject(value) {
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return {}; }
  }
  return value && typeof value === 'object' ? value : {};
}

return responses.map((item, index) => {
  const ctx = handoffs[index]?.json?.ctx;
  const r = parseObject(item.json);
  const raw = parseObject(r.body ?? r);
  const d = parseObject(raw.result ?? raw.data ?? raw);
  const errors = [];

  if (!ctx?.input) {
    return {
      json: {
        ok: false,
        stage: 'draft_check',
        errors: ['Matching handoff context is missing.']
      }
    };
  }

  const i = ctx.input;

  if (r.error || raw.error || d.detail) {
    errors.push('Draft PO request failed: ' +
      JSON.stringify(r.error ?? raw.error ?? d.detail).slice(0, 300));
  } else {
    if (d.supplier_id !== i.supplier_id)
      errors.push('Draft supplier does not match handoff.');

    if (d.part_id !== i.part_id)
      errors.push('Draft part does not match handoff.');

    if (Number(d.qty) !== Number(i.qty))
      errors.push('Draft quantity does not match handoff.');

    if (!d.po_id)
      errors.push('Draft response is missing the PO ID.');
  }

  const value = Number(d.value_aed);

  if (!Number.isFinite(value) || value <= 0) {
    errors.push('Draft PO value is missing or invalid. Approval check cannot proceed.');
  }

  ctx.draft = errors.length ? null : d;

  ctx.needs_approval =
    Number.isFinite(value) &&
    value > ctx.config.approval_limit_aed ||
    d.approval_required === true;

  return {
    json: {
      ok: errors.length === 0,
      stage: 'draft_check',
      errors,
      ctx
    }
  };
});

