// FIX: only drafts that were actually sent for approval, so answers line up with the right PO.
const drafts = $('4b. Check draft matches handoff').all()
  .filter(i => i.json?.ok === true && i.json?.ctx?.needs_approval === true);
const responses = $input.all();

function parseObject(value) {
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return {}; }
  }
  return value && typeof value === 'object' ? value : {};
}

return responses.map((item, index) => {
  const ctx = drafts[index]?.json?.ctx;
  const r = parseObject(item.json);
  const body = parseObject(r.body ?? r);
  const a = parseObject(body.result ?? body.data ?? body);

  if (!ctx) {
    return {
      json: {
        ok: false,
        stage: 'approval',
        errors: ['Matching purchase order context is missing.']
      }
    };
  }

  const decision = String(a.decision ?? '').trim().toLowerCase();
  const errors = [];

  if (r.error || body.error || a.detail) {
    errors.push('Approval request failed: ' +
      JSON.stringify(r.error ?? body.error ?? a.detail).slice(0, 300));
  }

  if (decision !== 'approved') {
    errors.push('Approval not given. Decision: ' + (decision || 'missing'));
  }

  if (a.po_id && a.po_id !== ctx.draft.po_id) {
    errors.push('Approval response PO ID does not match the drafted PO.');
  }

  const approved = errors.length === 0;

  ctx.approval = {
    required: true,
    approved,
    decision: decision || null,
    error: errors.length ? errors.join('; ') : null
  };

  return {
    json: {
      ok: approved,
      stage: 'approval',
      errors,
      ctx
    }
  };
});

const items = $input.all();

return items.map(item => {
  const ctx = item.json.ctx;
  const errors = [];

  if (!ctx || !ctx.input || !ctx.supplier) {
    return {
      json: {
        ok: false,
        stage: 'final_check',
        errors: ['Missing procurement context or supplier profile.']
      }
    };
  }

  const d = ctx.draft;
  const i = ctx.input;
  const supplier = ctx.supplier;

  if (!d || !d.po_id)
    errors.push('Missing draft purchase order.');

  if (d?.sent === true)
    errors.push('PO has already been sent.');

  if (d && d.supplier_id !== i.supplier_id)
    errors.push('Draft supplier does not match handoff.');

  if (d && d.part_id !== i.part_id)
    errors.push('Draft part does not match handoff.');

  if (d && Number(d.qty) !== Number(i.qty))
    errors.push('Draft quantity does not match handoff.');

  if (d?.mode && d.mode !== i.mode)
    errors.push('Draft shipping mode does not match handoff.');

  if (d?.quote_id && d.quote_id !== i.quote_id)
    errors.push('Draft quote reference does not match handoff.');

  const value = Number(d?.value_aed);
  if (!Number.isFinite(value) || value <= 0)
    errors.push('Invalid or missing PO value.');

  const limit = Number(ctx.config?.approval_limit_aed);

  if (!Number.isFinite(limit))
    errors.push('Approval limit is missing or invalid.');

  const mustApprove =
    ctx.needs_approval === true ||
    (Number.isFinite(value) && Number.isFinite(limit) && value > limit) ||
    d?.approval_required === true;

  if (mustApprove && ctx.approval?.approved !== true)
    errors.push('Required approval is missing or not approved.');

  const domain = String(supplier.email_domain ?? '')
    .trim()
    .toLowerCase()
    .replace(/^@/, '');

  const recipient = String(ctx.recipient ?? '')
    .trim()
    .toLowerCase();

  const expectedRecipient = domain ? `orders@${domain}` : '';

  if (!domain || !/^[a-z0-9.-]+\.[a-z]{2,}$/.test(domain))
    errors.push('Supplier registered email domain is invalid.');

  if (!expectedRecipient || recipient !== expectedRecipient)
    errors.push('Recipient does not match the approved supplier email address.');

  if (!errors.length) {
    ctx.approval = ctx.approval ?? {
      required: false,
      approved: true,
      decision: 'not required'
    };

    // Use a fixed template, not free-form Llama-generated email text.
    ctx.email = {
      to: expectedRecipient,
      subject: `Purchase Order ${d.po_id} - ${d.part_id} x ${d.qty}`,
      body:
        `Dear ${supplier.supplier_name || 'Supplier'},\n\n` +
        `Please find the purchase order details below:\n\n` +
        `PO: ${d.po_id}\n` +
        `Part: ${d.part_id}\n` +
        `Quantity: ${d.qty} pcs\n` +
        `Unit price: AED ${d.unit_price_aed}\n` +
        `Total: AED ${d.value_aed}\n` +
        `Shipping: ${d.mode || i.mode}\n` +
        `Quote reference: ${d.quote_id || i.quote_id}\n\n` +
        `Please confirm receipt of this purchase order and the planned ship date.\n\n` +
        `Regards,\nProcurement Team`
    };
  } else {
    ctx.email = null;
  }

  return {
    json: {
      ok: errors.length === 0,
      stage: 'final_check',
      errors,
      ctx
    }
  };
});

// FIX: only items that passed the final check were emailed, so line up with those.
const checks = $('6. Final safety check before send').all()
  .filter(i => i.json?.ok === true);
const responses = $input.all();

function parseObject(value) {
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return {}; }
  }
  return value && typeof value === 'object' ? value : {};
}

return responses.map((item, index) => {
  const ctx = checks[index]?.json?.ctx;
  const r = parseObject(item.json);
  const body = parseObject(r.body ?? r);
  const s = parseObject(body.result ?? body.data ?? body);

  if (!ctx || !ctx.draft) {
    return {
      json: {
        agent: 'agent5_procurement_approval',
        status: 'send_failed',
        sent: false,
        errors: ['Missing validated procurement context.']
      }
    };
  }

  const d = ctx.draft;

  // Require explicit confirmation from the simulator.
  const sent =
    !r.error &&
    !body.error &&
    !s.error &&
    !s.detail &&
    (s.ok === true || s.sent === true || s.status === 'sent');

  const errors = sent
    ? []
    : ['Email was not confirmed as sent: ' +
       JSON.stringify(r.error ?? body.error ?? s.detail ?? s.error ?? s)];

  return {
    json: {
      agent: 'agent5_procurement_approval',
      status: sent ? 'po_sent' : 'send_failed',
      scenario_id: ctx.input.scenario_id,
      incident_id: ctx.input.incident_id,
      quote_id: ctx.input.quote_id,
      po_id: d.po_id,
      supplier_id: d.supplier_id,
      part_id: d.part_id,
      qty: d.qty,
      mode: d.mode,
      value_aed: d.value_aed,
      approval_required: ctx.needs_approval,
      approval_status: ctx.approval?.decision ?? 'not_required',
      sent,
      recipient: ctx.email?.to ?? null,
      send_error: sent ? null : errors[0],
      disrupted_supplier_id: ctx.input.disrupted_supplier_id ?? null,
      justification: ctx.text?.justification ?? null,
      selection_reason: ctx.text?.selection_reason ?? null,
      llm_used: ctx.text?.llm_used ?? false,
      errors
    }
  };
});

const items = $input.all();

// Outcomes the design intends. Not faults.
const EXPECTED_OUTCOMES = new Set([
  'escalate_no_valid_quotes',
  'escalate_no_on_time_quote',
  'escalate_no_faster_option',
  'escalate_no_alternative_supplier',
  'needs_human_review',
  'no_action_needed'
]);

const statusByStage = {
  validate_input: 'rejected_bad_input',
  blocked_before_procurement: 'escalated_for_buyer_decision',
  supplier_check: 'blocked_supplier_not_qualified',
  draft_check: 'blocked_draft_mismatch',
  approval: 'approval_rejected',
  final_check: 'blocked_safety_check'
};

return items.map(item => {
  const { stage, ctx } = item.json;
  const rawNotes = item.json.errors;

  const notes = Array.isArray(rawNotes)
    ? rawNotes
    : rawNotes
      ? [String(rawNotes)]
      : ['Workflow stopped without further detail.'];

  const expected = EXPECTED_OUTCOMES.has(item.json.handoff_status);

  const d = ctx?.draft ?? {};
  const i = ctx?.input ?? {};

  return {
    json: {
      agent: 'agent5_procurement_approval',
      status: statusByStage[stage] ?? 'stopped',
      outcome: expected ? 'escalated' : 'blocked',

      scenario_id: i.scenario_id ?? null,
      incident_id: i.incident_id ?? null,
      quote_id: i.quote_id ?? null,
      po_id: d.po_id ?? null,
      supplier_id: i.supplier_id ?? null,
      part_id: i.part_id ?? null,
      qty: i.qty ?? null,
      value_aed: d.value_aed ?? null,

      approval_required: ctx?.needs_approval ?? null,
      approval_status: ctx?.approval?.decision ?? null,
      sent: false,
      stopped_at: stage ?? 'unknown',

      // Why a human is being asked to decide.
      escalation_reasons: expected ? notes : [],

      // Genuine faults only. Empty is good news.
      errors: expected ? [] : notes,

      advisor_recommendation: item.json.advisor_recommendation ?? null,
      advisor_recommended_option: item.json.advisor_recommended_option ?? null,
      advisor_tradeoffs: item.json.advisor_tradeoffs ?? null,
      advisor_question_for_buyer: item.json.advisor_question_for_buyer ?? null,

      next_step: expected
        ? 'Buyer decision required. Do not order automatically.'
        : 'Investigate before retrying. Do not resend automatically.'
    }
  };
});

