// Gathers every result of this run (sent and not sent) into one list,
// so the orchestrator gets all of them even when items took different paths.
const names = ['8. Result: PO sent', 'Result: NOT sent (stopped)'];
const seen = new Set();
const out = [];

for (const name of names) {
  for (let run = 0; run < 50; run++) {
    let items;

    try {
      items = $(name).all(0, run);
    } catch (e) {
      break;   // node has not run, or no such run
    }

    if (!items || !items.length) break;

    for (const it of items) {
      const key = JSON.stringify(it.json);
      if (seen.has(key)) continue;
      seen.add(key);
      out.push({ json: it.json });
    }
  }
}

// Safety net: never return less than what just arrived.
return out.length ? out : $input.all();

// Reads the AI Agent's reply (field "output") as JSON. Also accepts the old
// chat-completions shape, code fences, or extra text around the JSON.
function readAgentJson(r) {
  let c = r?.output ?? r?.choices?.[0]?.message?.content ?? r?.text;
  if (c && typeof c === 'object') return c;
  if (typeof c !== 'string') return {};
  c = c.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  try { return JSON.parse(c); } catch (e) {}
  const a = c.indexOf('{');
  const b = c.lastIndexOf('}');
  if (a !== -1 && b > a) {
    try { return JSON.parse(c.slice(a, b + 1)); } catch (e) {}
  }
  return {};
}

// FIX: handle EVERY item, not only the first one.
// Llama responses come back in the same order as the items that passed 'Supplier OK?'.
const checks = $('2b. Check supplier is qualified').all()
  .map(i => i.json)
  .filter(j => j && j.ok === true && j.ctx);

const responses = $input.all();

const clean = (s, max) =>
  String(s ?? '').replace(/\s+/g, ' ').trim().slice(0, max);

return responses.map((item, index) => {
  const ctx = checks[index]?.ctx;

  if (!ctx || !ctx.input || !ctx.supplier) {
    throw new Error('Supplier handoff is missing input or supplier data. Execute the upstream nodes again.');
  }

  const r = item.json ?? {};

  let t = {};

  t = readAgentJson(r);

  if (!t || typeof t !== 'object') t = {};

  const i = ctx.input;

  const fallbackReason =
    `Shortage of ${i.part_id} affects production orders ${i.affected_orders.join(', ') || '(see incident)'}. ` +
    `Ordering ${i.qty} pcs by ${i.mode} from ${ctx.supplier.role} supplier ${ctx.supplier.supplier_id} to cover the shortage by the requested date ${i.need_date ?? 'not specified'}.`;

  // The supplier-choice reason comes from Agent 4's code, never from the AI,
  // so IDs, prices and dates in it are always the real ones.
  const selectionReason = clean(i.selection_reason, 700);

  const withReason = text =>
    selectionReason ? `${text} Supplier choice: ${selectionReason}` : text;

  ctx.text = {
    selection_reason: selectionReason || null,
    llm_used: !!t.justification,
    llm_error: r.error ? JSON.stringify(r.error).slice(0, 300) : null,
    justification: withReason(clean(t.justification, 500) || fallbackReason),
    approval_reason: clean(t.approval_reason, 900) || fallbackReason,
    email_body: String(t.email_body ?? '').trim().slice(0, 1500) ||
      `Dear ${ctx.supplier.supplier_name || 'Supplier'},\n\nPlease confirm availability and delivery schedule for the requested items.\n\nRegards,\nProcurement Team`
  };

  return {
    json: {
      ok: true,
      stage: 'write_text',
      errors: [],
      ctx
    }
  };
});
